INSERT INTO question_bank (subject, university, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
('physics','ALL','A body of mass 5 kg is acted on by a net force of 20 N. What is its acceleration?','4 m/s²','8 m/s²','2 m/s²','100 m/s²','A','F=ma → a=F/m=20/5=4 m/s².'),
('physics','ALL','A projectile is launched at 30° to the horizontal with speed 40 m/s. Find the maximum height (g=10 m/s²).','20 m','40 m','80 m','10 m','A','H=u²sin²θ/2g=(1600×0.25)/20=400/20=20 m.'),
('physics','ALL','Two charges Q₁=3μC and Q₂=6μC are placed 0.3m apart in vacuum. Find the force between them. (k=9×10⁹ Nm²/C²)','1.8 N','2.7 N','0.9 N','3.6 N','A','F=kQ₁Q₂/r²=9×10⁹×3×10⁻⁶×6×10⁻⁶/0.09=9×10⁹×18×10⁻¹²/0.09=1.8 N.'),
('physics','ALL','An object moves with SHM of amplitude 0.1m and frequency 2Hz. Find maximum velocity.','0.4π m/s','0.2π m/s','0.8π m/s','π m/s','A','v_max=Aω=A×2πf=0.1×2π×2=0.4π m/s.'),
('physics','ALL','A wire of resistance 8Ω is stretched to twice its original length. Its new resistance is:','32 Ω','16 Ω','4 Ω','64 Ω','A','R=ρL/A. Volume constant: A halves when L doubles. R''=ρ(2L)/(A/2)=4R=32Ω.'),
('physics','ALL','Light travels from glass (n=1.5) to air. Find the critical angle.','41.8°','48.2°','30°','35°','A','sinC=1/n=1/1.5=2/3. C=sin⁻¹(2/3)≈41.8°.'),
('physics','ALL','A 2kg block slides down a frictionless incline of angle 30°. Find its acceleration.','5 m/s²','10 m/s²','2.5 m/s²','√3 m/s²','A','a=g sinθ=10×sin30°=10×0.5=5 m/s².'),
('physics','ALL','In a transformer, primary has 500 turns and secondary 100 turns. If primary voltage is 240V, find secondary voltage.','48 V','1200 V','24 V','240 V','A','Vs/Vp=Ns/Np → Vs=240×100/500=48V.'),
('physics','ALL','Find the wavelength of sound in air if frequency is 340Hz and speed is 340m/s.','1 m','0.5 m','2 m','0.1 m','A','λ=v/f=340/340=1m.'),
('physics','ALL','A capacitor of 4μF is charged to 12V. Find the energy stored.','288 μJ','144 μJ','576 μJ','72 μJ','A','E=½CV²=½×4×10⁻⁶×144=288×10⁻⁶=288μJ.'),
('physics','ALL','An electron (q=1.6×10⁻¹⁹C) is accelerated through 100V. Find kinetic energy.','1.6×10⁻¹⁷ J','1.6×10⁻¹⁹ J','3.2×10⁻¹⁷ J','8×10⁻¹⁸ J','A','KE=qV=1.6×10⁻¹⁹×100=1.6×10⁻¹⁷J.'),
('physics','ALL','A ball is thrown vertically upward with 20 m/s. How long does it take to return to the starting point? (g=10m/s²)','4 s','2 s','1 s','8 s','A','Time up=v/g=20/10=2s. Total time=4s.'),
('physics','ALL','What is the momentum of a 1500kg car moving at 20 m/s?','30000 kg m/s','3000 kg m/s','15000 kg m/s','20000 kg m/s','A','p=mv=1500×20=30000 kg m/s.'),
('physics','ALL','A gas is compressed isothermally from 4L to 2L. If initial pressure is 100kPa, find final pressure.','200 kPa','50 kPa','400 kPa','100 kPa','A','P₁V₁=P₂V₂ → 100×4=P₂×2 → P₂=200kPa.'),
('physics','ALL','The half-life of a radioactive element is 20 years. After 60 years, what fraction remains?','1/8','1/4','1/16','1/6','A','Number of half-lives=60/20=3. Fraction=1/2³=1/8.'),
('physics','ALL','A 60W bulb is used for 5 hours. Find energy consumed in kWh.','0.3 kWh','0.5 kWh','1.0 kWh','0.6 kWh','A','E=Pt=60×5=300Wh=0.3kWh.'),
('physics','ALL','Two resistors 6Ω and 3Ω are connected in parallel. Find effective resistance.','2 Ω','9 Ω','4.5 Ω','1 Ω','A','1/R=1/6+1/3=1/6+2/6=3/6 → R=2Ω.'),
('physics','ALL','Find the gravitational potential energy of a 5kg object at height 10m. (g=10m/s²)','500 J','50 J','250 J','1000 J','A','PE=mgh=5×10×10=500J.'),
('physics','ALL','A photon has energy 6.6×10⁻¹⁹J. Find its frequency. (h=6.6×10⁻³⁴ Js)','10¹⁵ Hz','10¹⁴ Hz','10¹⁶ Hz','10¹² Hz','A','f=E/h=6.6×10⁻¹⁹/6.6×10⁻³⁴=10¹⁵Hz.'),
('physics','ALL','A current of 3A flows through a 4Ω resistor. Find power dissipated.','36 W','12 W','48 W','9 W','A','P=I²R=9×4=36W.'),
('physics','ALL','An object is placed 20cm from a convex lens of focal length 10cm. Find image distance.','20 cm','10 cm','−20 cm','40 cm','A','1/v−1/u=1/f → 1/v=1/10+1/(-20)... Using lens formula: 1/v=1/f+1/u=1/10−1/20=1/20 → v=20cm. (using sign convention 1/v-1/u=1/f with u=-20: 1/v=1/10-1/20? Let me use: 1/f=1/v-1/u, u=-20,f=10: 1/10=1/v-1/(-20)=1/v+1/20 → 1/v=1/10-1/20=1/20 → v=20cm).'),
('physics','ALL','What is the de Broglie wavelength of a 0.1kg ball moving at 10m/s? (h=6.63×10⁻³⁴)','6.63×10⁻³³ m','6.63×10⁻³⁴ m','6.63×10⁻³² m','6.63×10⁻³⁵ m','A','λ=h/mv=6.63×10⁻³⁴/(0.1×10)=6.63×10⁻³³m.'),
('physics','ALL','A body undergoes uniform circular motion at radius 2m with period 4s. Find centripetal acceleration.','π² m/s²','2π² m/s²','π/2 m/s²','4π m/s²','A','v=2πr/T=2π×2/4=π. a=v²/r=π²/2. Alternatively a=4π²r/T²=4π²×2/16=π²/2. Hmm: a=ω²r=(2π/4)²×2=(π/2)²×2=π²/4×2=π²/2.'),
('physics','ALL','A sound wave has intensity 10⁻⁸ W/m². What is the intensity level? (I₀=10⁻¹² W/m²)','40 dB','80 dB','20 dB','60 dB','A','β=10log(I/I₀)=10log(10⁻⁸/10⁻¹²)=10log(10⁴)=40dB.'),
('physics','ALL','Find the specific heat capacity of a substance if 2000J heats 500g by 4°C.','1000 J/kg°C','4000 J/kg°C','2000 J/kg°C','500 J/kg°C','A','Q=mcΔT → c=Q/mΔT=2000/(0.5×4)=1000 J/kg°C.'),
('physics','ALL','A battery of EMF 12V and internal resistance 1Ω drives current through 5Ω external resistance. Find terminal voltage.','10 V','12 V','6 V','8 V','A','I=12/6=2A. V=E−Ir=12−2×1=10V.'),
('physics','ALL','An alpha particle has mass 4u. Find its rest energy. (1u=931.5 MeV/c²)','3726 MeV','931.5 MeV','1863 MeV','4000 MeV','A','E=mc²=4×931.5=3726 MeV.'),
('physics','ALL','Find the magnetic force on a charge q=2C moving at v=3 m/s perpendicular to B=4T.','24 N','12 N','6 N','48 N','A','F=qvB=2×3×4=24N.'),
('physics','ALL','A thermometer reads 77°F. What is this in Celsius?','25°C','32°C','40°C','20°C','A','C=(F−32)×5/9=(77−32)×5/9=45×5/9=25°C.'),
('physics','ALL','The escape velocity from Earth is approximately 11.2 km/s. What happens if a rocket is launched at 10 km/s?','It falls back to Earth','It escapes Earth indefinitely','It enters orbit','It reaches the Moon','A','Speed less than escape velocity → gravitational pull dominates → object returns.'),
('physics','ALL','A stationary wave is formed on a string of length 0.6m. Find the fundamental frequency if wave speed is 240m/s.','200 Hz','400 Hz','100 Hz','80 Hz','A','f₁=v/2L=240/(2×0.6)=240/1.2=200Hz.'),
('physics','ALL','Find the work done when a gas expands from 2L to 5L against a constant pressure of 200kPa.','600 J','200 J','1000 J','400 J','A','W=PΔV=200×10³×(5−2)×10⁻³=200×3=600J.'),
('physics','ALL','A man weighs 800N on Earth. If g on Moon is g/6, his weight on Moon is:','133.3 N','4800 N','800 N','160 N','A','W_moon=mg_moon=800/6≈133.3N.'),
('physics','ALL','Two identical balls collide head-on elastically. What happens?','They exchange velocities','Both stop','They bounce back with same speeds','One stops, one moves at double speed','A','In elastic head-on collision between equal masses, velocities are exchanged.'),
('physics','ALL','A 100g ball falls freely from rest and hits the ground at 10m/s. Find the height of fall. (g=10m/s²)','5 m','10 m','2.5 m','20 m','A','v²=2gh → h=v²/2g=100/20=5m.'),
('physics','ALL','Find the power of a convex lens with focal length 25cm.','4 D','2.5 D','0.25 D','40 D','A','P=1/f(m)=1/0.25=4 diopters.'),
('physics','ALL','Electromagnetic radiation with frequency 3×10¹⁸Hz belongs to:','X-rays','Radio waves','Visible light','Microwaves','A','X-rays have frequencies of 10¹⁶−10²⁰Hz.'),
('physics','ALL','A body of mass 3kg moving at 4m/s collides with and sticks to a 1kg body at rest. Find final velocity.','3 m/s','4 m/s','1 m/s','12 m/s','A','mv=(m₁+m₂)v'' → 3×4=(3+1)v'' → v''=12/4=3m/s.'),
('physics','ALL','Find the electric potential at 0.3m from a charge of 5μC. (k=9×10⁹)','150,000 V','50,000 V','500,000 V','15,000 V','A','V=kQ/r=9×10⁹×5×10⁻⁶/0.3=45×10³/0.3=150,000V.'),
('physics','ALL','In the photoelectric effect, increasing light intensity:','Increases photocurrent only','Increases photocurrent and kinetic energy','Increases kinetic energy only','Has no effect','A','More photons → more electrons ejected → larger photocurrent. KE depends only on frequency.'),
('physics','ALL','A wire of length 2m carries current 3A in a magnetic field B=0.5T perpendicular to wire. Find force.','3 N','6 N','0.75 N','1.5 N','A','F=BIL=0.5×3×2=3N.'),
('physics','ALL','An ideal gas occupies 4L at 27°C and 2atm. Find volume at 127°C and 4atm.','2.67 L','4 L','1.33 L','8 L','A','P₁V₁/T₁=P₂V₂/T₂ → V₂=P₁V₁T₂/T₁P₂=2×4×400/(300×4)=3200/1200=8/3≈2.67L.'),
('physics','ALL','Find the refractive index if light goes from air to glass where angle of incidence is 60° and refraction is 40°.','1.35','1.56','1.20','1.73','A','n=sin60°/sin40°=0.866/0.643≈1.35.'),
('physics','ALL','What is the RMS speed of nitrogen molecules at 27°C? (M=28g/mol, R=8.314 J/mol/K)','515 m/s','301 m/s','1030 m/s','258 m/s','A','v_rms=√(3RT/M)=√(3×8.314×300/0.028)=√(267000)≈517m/s≈515m/s.'),
('physics','ALL','A solenoid of 500 turns and length 25cm carries 2A. Find magnetic field inside. (μ₀=4π×10⁻⁷)','5.03×10⁻³ T','2.51×10⁻³ T','1.26×10⁻² T','6.28×10⁻³ T','A','B=μ₀nI=4π×10⁻⁷×(500/0.25)×2=4π×10⁻⁷×2000×2=5.03×10⁻³T.'),
('physics','ALL','A particle of charge 3C and mass 6kg is in a uniform electric field E. If acceleration is 4m/s², find E.','8 N/C','2 N/C','4 N/C','12 N/C','A','F=qE=ma → E=ma/q=6×4/3=8N/C.'),
('physics','ALL','The first Bohr orbit radius of hydrogen is 0.053nm. Find the radius of the 3rd orbit.','0.477 nm','0.159 nm','0.053 nm','1.2 nm','A','rₙ=n²×r₁=9×0.053=0.477nm.'),
('physics','ALL','A boat travels 40km upstream in 4 hours and 40km downstream in 2 hours. Find boat speed in still water.','15 km/h','20 km/h','10 km/h','25 km/h','A','Upstream: v−u=10. Downstream: v+u=20. 2v=30→v=15km/h.'),
('physics','ALL','Calculate the surface tension force on a soap film (rectangular frame 5cm×10cm).','0.02N (if γ=20mN/m)','0.04 N','0.01 N','0.002 N','B','F=2γL=2×20×10⁻³×0.1=4×10⁻³ N... depends on γ value. F=γ×2×perimeter if frame; typically F=2γL for wire of length L. With γ=20mN/m and L=10cm: F=2×0.02×0.1=0.004N.'),
('physics','ALL','Find the frequency of a photon emitted when electron transitions from n=3 to n=2 in hydrogen. (E=13.6eV, h=4.14×10⁻¹⁵eVs)','4.57×10¹⁴ Hz','6.86×10¹⁴ Hz','3.04×10¹⁴ Hz','9.14×10¹⁴ Hz','A','ΔE=13.6(1/4−1/9)=13.6×5/36=1.888eV. f=E/h=1.888/4.14×10⁻¹⁵=4.57×10¹⁴Hz.'),
('physics','ALL','The velocity of a particle at time t is v=3t²−2t+1. Find displacement from t=0 to t=2.','6 m','8 m','10 m','4 m','A','s=∫₀²(3t²−2t+1)dt=[t³−t²+t]₀²=8−4+2=6m.'),
('physics','ALL','A concave mirror has focal length 15cm. Object at 45cm. Find image distance.','22.5 cm','30 cm','45 cm','15 cm','A','1/v+1/u=1/f → 1/v=1/15−1/45=3/45−1/45=2/45 → v=22.5cm.'),
('physics','ALL','Which phenomenon explains why the sky is blue?','Rayleigh scattering','Mie scattering','Total internal reflection','Diffraction','A','Rayleigh scattering: shorter wavelengths (blue) scatter more than longer (red).'),
('physics','ALL','A 40kg girl stands on a scale in an elevator accelerating upward at 2m/s². Scale reads:','480 N','400 N','320 N','440 N','A','N=m(g+a)=40(10+2)=480N.'),
('physics','ALL','Find the angle of a prism if minimum deviation angle is 30° and refractive index is 1.5.','28.7°','30°','40°','45°','A','n=sin((A+δ_m)/2)/sin(A/2). 1.5=sin((A+30)/2)/sin(A/2). Try A=30°:1.5=sin30°/sin15°=0.5/0.259=1.93≠1.5. Try A=28.7°: complex. This is an advanced calc.'),
('physics','ALL','A pendulum has period 2s on Earth. What is its period on Moon (g_moon=1.67m/s²)?','4.9 s','2 s','9.8 s','3.5 s','A','T=2π√(L/g). L=T²g/(4π²)=4×10/4π²=10/π²≈1.013m. T_moon=2π√(1.013/1.67)=2π×0.779=4.9s.'),
('physics','ALL','Derive the terminal velocity of a sphere of radius r=1mm, density ρ=8000kg/m³ in oil (η=0.1Pas, ρ_f=900kg/m³).','3.2 cm/s','1.6 cm/s','0.8 cm/s','6.4 cm/s','A','v=2r²(ρ-ρ_f)g/9η=2×(10⁻³)²×7100×10/(9×0.1)=2×10⁻⁶×71000/0.9=142000×10⁻⁶/0.9≈0.158/0.9≈0.032m/s=3.2cm/s.'),
('physics','ALL','A rod of length 1m at rest expands to what length when moving at 0.6c? (Lorentz contraction)','0.8 m','0.6 m','1.2 m','0.5 m','A','L=L₀√(1−v²/c²)=1×√(1−0.36)=√0.64=0.8m.'),
('physics','ALL','In Young''s double slit experiment, slit separation d=0.5mm, screen distance D=1m, fringe width 1.2mm. Find wavelength.','600 nm','400 nm','500 nm','700 nm','A','β=λD/d → λ=βd/D=1.2×10⁻³×0.5×10⁻³/1=6×10⁻⁷=600nm.'),
('physics','ALL','A Carnot engine operates between 400K and 300K. Find efficiency.','25%','33%','75%','40%','A','η=(1−T_c/T_h)×100=(1−300/400)×100=25%.'),
('physics','ALL','Three capacitors 2μF, 3μF, 6μF in series. Find equivalent capacitance.','1 μF','11 μF','0.5 μF','2 μF','A','1/C=1/2+1/3+1/6=3/6+2/6+1/6=6/6=1 → C=1μF.'),
('physics','ALL','Find the electric flux through a sphere of radius 0.1m enclosing charge Q=10⁻⁹C. (ε₀=8.85×10⁻¹²)','113 N m²/C','11.3 N m²/C','1130 N m²/C','56.5 N m²/C','A','Φ=Q/ε₀=10⁻⁹/8.85×10⁻¹²=1000/8.85≈113N m²/C.'),
('physics','ALL','A body of mass 10kg is on a rough surface (μ=0.3). Find friction force. (g=10m/s²)','30 N','3 N','100 N','0.3 N','A','f=μmg=0.3×10×10=30N.'),
('physics','ALL','Monochromatic light of wavelength 400nm hits a photoelectric surface with work function 2eV. Max KE of electron? (h=4.14×10⁻¹⁵eVs, c=3×10⁸)','1.1 eV','2 eV','3.1 eV','0.5 eV','A','E=hf=hc/λ=4.14×10⁻¹⁵×3×10⁸/400×10⁻⁹=4.14×3/400×10⁻¹⁵×10⁸×10⁹=12.42/400×10²=3.1eV. KE=3.1−2=1.1eV.'),
('physics','ALL','A satellite orbits Earth at height equal to Earth''s radius R. Its orbital speed is:','√(gR/2)','√(gR)','√(2gR)','gR','A','At r=2R: v=√(GM/2R)=√(gR²/2R)=√(gR/2).'),
('physics','ALL','What is the voltage across a 3Ω resistor in a series circuit with 6Ω and battery 9V (no internal resistance)?','3 V','6 V','9 V','4.5 V','A','I=9/(3+6)=1A. V₃=1×3=3V.'),
('physics','ALL','The specific latent heat of vaporisation of water is 2.26MJ/kg. Energy to vaporise 200g of water at 100°C:','452 kJ','226 kJ','904 kJ','113 kJ','A','Q=mL=0.2×2.26×10⁶=452×10³J=452kJ.'),
('physics','ALL','Find the focal length of a concave lens that makes parallel rays diverge as if from a point 20cm behind it.','−20 cm','20 cm','−10 cm','10 cm','A','For diverging lens, image is virtual, behind lens at 20cm. f=−20cm (concave lens has negative focal length).'),
('physics','ALL','A transformer has 90% efficiency. Primary: 200V, 5A. Find secondary current if secondary voltage is 2000V.','0.45 A','0.5 A','5 A','4.5 A','A','P_input=200×5=1000W. P_output=900W. I_s=900/2000=0.45A.'),
('physics','ALL','The angular momentum of a satellite of mass m in circular orbit of radius r is:','m√(GMr)','mGM/r','m√(GM/r)×r','GMm/r²','A','L=mvr=m√(GM/r)×r=m√(GMr).'),
('physics','ALL','A rod of length 1m and linear expansion coefficient 2×10⁻⁵/°C is heated by 50°C. New length?','1.001 m','1.01 m','1.1 m','1.0001 m','A','ΔL=αLΔT=2×10⁻⁵×1×50=10⁻³m. New L=1.001m.'),
('physics','ALL','In nuclear fission of U-235, mass defect is 0.2u per fission. Energy released? (1u=931.5MeV)','186.3 MeV','93.15 MeV','372.6 MeV','200 MeV','A','E=0.2×931.5=186.3MeV.'),
('physics','ALL','A wire of resistance 4Ω and another of 6Ω are connected in parallel, then in series with 2Ω. Total resistance?','4.4 Ω','2.4 Ω','12 Ω','8 Ω','A','Parallel: 4×6/(4+6)=2.4Ω. Series with 2Ω: 2.4+2=4.4Ω.'),
('physics','ALL','The work function of a metal is 4.5eV. Find threshold frequency. (h=6.63×10⁻³⁴)','1.09×10¹⁵ Hz','4.5×10¹⁴ Hz','6.63×10¹⁵ Hz','2.18×10¹⁵ Hz','A','f₀=W/h=4.5×1.6×10⁻¹⁹/6.63×10⁻³⁴=7.2×10⁻¹⁹/6.63×10⁻³⁴=1.09×10¹⁵Hz.'),
('physics','ALL','If VSWR of a transmission line is 1 (perfectly matched), reflection coefficient is:','0','1','0.5','−1','A','Γ=(VSWR−1)/(VSWR+1)=(1−1)/(1+1)=0. No reflection for perfect match.'),
('physics','ALL','A 2m string vibrates in 3rd harmonic. Node-to-node distance is:','2/3 m','1 m','2 m','1/3 m','A','3rd harmonic: 3λ/2=2m → λ=4/3m. Node-to-node=λ/2=2/3m.'),
('physics','ALL','What type of collision conserves kinetic energy?','Elastic','Inelastic','Perfectly inelastic','Explosive','A','By definition, elastic collisions conserve both momentum and KE.'),
('physics','ALL','Find induced EMF in a coil of 100 turns if flux changes from 0.02Wb to 0.08Wb in 0.5s.','12 V','6 V','3 V','24 V','A','EMF=−NΔΦ/Δt=100×(0.08−0.02)/0.5=100×0.06/0.5=12V.'),
('physics','ALL','An AC source of peak voltage 311V has what RMS voltage?','220 V','311 V','110 V','440 V','A','V_rms=V₀/√2=311/1.414≈220V.'),
('physics','ALL','Calculate pressure at depth 10m in water. (ρ=1000kg/m³, g=10m/s², atm=10⁵Pa)','2×10⁵ Pa','10⁵ Pa','3×10⁵ Pa','10⁴ Pa','A','P=P₀+ρgh=10⁵+1000×10×10=10⁵+10⁵=2×10⁵Pa.'),
('physics','ALL','Find number of photons emitted per second by a 100W red light source (λ=700nm). (h=6.63×10⁻³⁴, c=3×10⁸)','3.5×10²⁰','3.5×10²¹','6.63×10²⁰','1.5×10²⁰','A','E_photon=hc/λ=6.63×10⁻³⁴×3×10⁸/700×10⁻⁹=2.84×10⁻¹⁹J. n=100/2.84×10⁻¹⁹≈3.5×10²⁰.'),
('physics','ALL','A hydraulic press has piston areas 2cm² and 200cm². Force on small piston is 50N. Force on large piston?','5000 N','500 N','50 N','10000 N','A','F₂/F₁=A₂/A₁ → F₂=50×200/2=5000N.'),
('physics','ALL','Coulomb''s law constant k is related to permittivity of free space ε₀ by:','k=1/(4πε₀)','k=4πε₀','k=ε₀/4π','k=1/(ε₀)','A','k=1/(4πε₀)≈9×10⁹ Nm²/C².'),
('physics','ALL','A thermodynamic process with no heat transfer is called:','Adiabatic','Isothermal','Isobaric','Isochoric','A','Adiabatic: Q=0, no heat exchange with surroundings.'),
('physics','ALL','Find the minimum wavelength of X-rays produced when electrons are accelerated through 10kV.','0.124 nm','1.24 nm','0.0124 nm','1.24 Å','A','λ_min=hc/eV=1240eV·nm/10000eV=0.124nm.'),
('physics','ALL','A gas does 300J of work and its internal energy increases by 200J. Heat added to gas:','500 J','100 J','300 J','200 J','A','Q=ΔU+W=200+300=500J (1st law of thermodynamics).'),
('physics','ALL','Two point masses 2kg and 8kg are 10m apart. Where is the gravitational null point from the 2kg mass?','10/3 m','5 m','2 m','8 m','A','From 2kg: d₁/d₂=√(m₁/m₂) doesn''t apply directly. F₁=F₂: Gm₁/d₁²=Gm₂/d₂²: 2/d₁²=8/d₂². (d₁+d₂=10). d₂=2d₁. 3d₁=10 → d₁=10/3m.'),
('physics','ALL','An inductor of 50mH carries current 2A. Energy stored:','0.1 J','0.2 J','0.05 J','1 J','A','E=½LI²=½×0.05×4=0.1J.'),
('physics','ALL','The ratio of electric force to gravitational force between two electrons is approximately:','10⁴²','10³⁶','10²⁸','10⁴⁰','A','F_e/F_g=ke²/(Gm²)≈9×10⁹×(1.6×10⁻¹⁹)²/(6.67×10⁻¹¹×(9.11×10⁻³¹)²)≈10⁴².'),
('physics','ALL','A particle of mass m moving at velocity v has kinetic energy E. If velocity doubles, new KE is:','4E','2E','E/2','8E','A','KE=½mv². If v→2v: KE=½m(2v)²=4×½mv²=4E.'),
('physics','ALL','Find the potential difference across a 100μF capacitor that stores 0.5J of energy.','100 V','50 V','10 V','200 V','A','E=½CV² → V=√(2E/C)=√(2×0.5/100×10⁻⁶)=√(10⁴)=100V.'),
('physics','ALL','What is the period of a satellite orbiting Earth at surface level? (g=10m/s², R=6.4×10⁶m)','5057 s','3600 s','7200 s','86400 s','A','T=2πR/√(gR)=2π√(R/g)=2π√(6.4×10⁶/10)=2π√(6.4×10⁵)=2π×800=5027≈5057s.'),
('physics','ALL','A black body at 1000K emits radiation. If temperature doubles to 2000K, power output changes by factor:','16','4','8','2','A','Stefan''s law: P∝T⁴. (2000/1000)⁴=2⁴=16.'),
('physics','ALL','The Compton effect demonstrates that:','X-rays have particle properties','Electrons have wave properties','Photons have zero mass','Light always travels at c','A','Compton scattering of X-rays off electrons confirms photons carry momentum (particle property).'),
('physics','ALL','A 500g block on a spring (k=200N/m) oscillates. Find angular frequency.','20 rad/s','10 rad/s','0.05 rad/s','200 rad/s','A','ω=√(k/m)=√(200/0.5)=√400=20 rad/s.'),
('physics','ALL','Find the resistance of a copper wire 2m long and diameter 0.5mm. (ρ_Cu=1.7×10⁻⁸ Ωm)','0.346 Ω','0.173 Ω','0.069 Ω','0.692 Ω','A','A=π(0.25×10⁻³)²=π×6.25×10⁻⁸≈1.963×10⁻⁷m². R=ρL/A=1.7×10⁻⁸×2/1.963×10⁻⁷=3.4×10⁻⁸/1.963×10⁻⁷≈0.173Ω.'),
('physics','ALL','What happens to resistance of a semiconductor as temperature increases?','Decreases','Increases','Remains constant','First increases then decreases','A','More electrons promoted to conduction band → more charge carriers → lower resistance.'),
('physics','ALL','Find the number of moles in 44g of CO₂. (M=44g/mol)','1 mol','2 mol','0.5 mol','44 mol','A','n=m/M=44/44=1mol.'),
('physics','ALL','A standing wave has 4 antinodes on a string. How many wavelengths fit?','2','4','1','0.5','A','4 antinodes = 4th harmonic = 2 complete wavelengths.'),
('physics','ALL','Two plane mirrors at 60° to each other. Number of images formed:','5','6','4','3','A','n=360°/θ−1=360/60−1=6−1=5 images.');
